export type WaterfallStep = {
  label: string;
  base: number;
  delta: number;
  kind: 'total' | 'reduction' | 'result';
};

export type TreemapLeaf = {
  name: string;
  value: number;
  fill?: string;
};

export type StackedEmissionSegment = {
  label: string;
  value: number;
};

export type HotspotLollipopRow = {
  id: string;
  label: string;
  emissions: number;
  category?: string;
};

export type BenchmarkBulletRow = {
  label: string;
  value: number;
  kind: 'actual' | 'industry' | 'best' | 'previous';
};

const toSafe = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

/** Waterfall steps for reduction impact (stacked base + delta bars). */
export function buildReductionWaterfall(
  baselineKg: number,
  impacts: { label: string; impactKg: number }[]
): WaterfallStep[] {
  const baseline = Math.max(0, toSafe(baselineKg));
  if (baseline <= 0 && impacts.length === 0) {
    return [];
  }

  const rows: WaterfallStep[] = [
    { label: 'Current footprint', base: 0, delta: baseline, kind: 'total' },
  ];

  let running = baseline;
  impacts.forEach((imp, i) => {
    const reduction = Math.min(Math.max(0, toSafe(imp.impactKg)), running);
    if (reduction <= 0) {
      return;
    }
    const next = running - reduction;
    rows.push({
      label: (imp.label || `Action ${i + 1}`).slice(0, 42),
      base: next,
      delta: reduction,
      kind: 'reduction',
    });
    running = next;
  });

  rows.push({
    label: 'After recommended actions',
    base: 0,
    delta: running,
    kind: 'result',
  });

  return rows;
}

/** Flatten assessment stacked emissions rows for a 100% horizontal bar. */
export function flattenStackedEmissions(
  rows: Record<string, string | number>[] | undefined
): StackedEmissionSegment[] {
  if (!Array.isArray(rows) || rows.length === 0) {
    return [];
  }
  const first = rows[0];
  if (!first || typeof first !== 'object') {
    return [];
  }

  return Object.entries(first)
    .filter(([key]) => key !== 'name')
    .map(([key, val]) => ({
      label: key.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()),
      value: toSafe(val),
    }))
    .filter((s) => s.value > 0)
    .sort((a, b) => b.value - a.value);
}

/** Treemap leaves from category pie data. */
export function buildCategoryTreemap(
  categories: { label: string; value: number }[] | undefined,
  colors: string[]
): TreemapLeaf[] {
  if (!Array.isArray(categories) || categories.length === 0) {
    return [];
  }
  return categories
    .filter((c) => toSafe(c.value) > 0)
    .map((c, i) => ({
      name: c.label || 'Other',
      value: toSafe(c.value),
      fill: colors[i % colors.length],
    }));
}

/** Sparkline points from monthly scope stack. */
export function buildSparklineFromScopeStack(
  stack:
    | Array<{
        label?: string;
        period?: string;
        total?: number;
        scope1?: number;
        scope2?: number;
        scope3?: number;
      }>
    | undefined
): { label: string; total: number }[] {
  if (!Array.isArray(stack)) {
    return [];
  }
  return stack.map((row) => ({
    label: String(row.label || row.period || ''),
    total: toSafe(row.total) || toSafe(row.scope1) + toSafe(row.scope2) + toSafe(row.scope3),
  }));
}

export type DataQualitySegment = {
  tier: string;
  label: string;
  kgCO2e: number;
};

export type Scope3GhgSegment = {
  key: string;
  label: string;
  value: number;
  sharePercent?: number;
};

/** Data-quality tier mix for donut or bar charts. */
export function buildDataQualitySegments(
  rows: { tier: string; label: string; kgCO2e: number }[] | undefined
): DataQualitySegment[] {
  if (!Array.isArray(rows)) {
    return [];
  }
  return rows
    .filter((r) => toSafe(r.kgCO2e) > 0)
    .map((r) => ({
      tier: r.tier,
      label: r.label || r.tier,
      kgCO2e: toSafe(r.kgCO2e),
    }));
}

/** GHG Protocol Scope 3 category chart rows. */
export function buildScope3GhgSegments(
  rows: { key: string; label: string; value: number; sharePercent?: number }[] | undefined
): Scope3GhgSegment[] {
  if (!Array.isArray(rows)) {
    return [];
  }
  return rows
    .filter((r) => toSafe(r.value) > 0)
    .map((r) => ({
      key: r.key,
      label: (r.label || r.key).slice(0, 48),
      value: toSafe(r.value),
      sharePercent: r.sharePercent,
    }));
}

export function buildHotspotLollipops(
  hotspots: { id: string; label: string; co2: number; category?: string }[] | undefined
): HotspotLollipopRow[] {
  if (!Array.isArray(hotspots)) {
    return [];
  }
  return hotspots
    .map((h) => ({
      id: h.id,
      label: (h.label || 'Transaction').slice(0, 48),
      emissions: toSafe(h.co2),
      category: h.category,
    }))
    .filter((h) => h.emissions > 0)
    .sort((a, b) => b.emissions - a.emissions)
    .slice(0, 8);
}

export function buildBenchmarkBulletRows(
  actualKg: number,
  benchmarks?: {
    industryAverageKg?: number;
    bestInClassKg?: number;
    previousAssessmentKg?: number;
  }
): BenchmarkBulletRow[] {
  const actual = toSafe(actualKg);
  if (actual <= 0) {
    return [];
  }
  const rows: BenchmarkBulletRow[] = [{ label: 'Your footprint', value: actual, kind: 'actual' }];
  const industry = toSafe(benchmarks?.industryAverageKg);
  const best = toSafe(benchmarks?.bestInClassKg);
  const previous = toSafe(benchmarks?.previousAssessmentKg);
  if (industry > 0) {
    rows.push({ label: 'Industry average', value: industry, kind: 'industry' });
  }
  if (best > 0) {
    rows.push({ label: 'Best in class', value: best, kind: 'best' });
  }
  if (previous > 0) {
    rows.push({ label: 'Previous assessment', value: previous, kind: 'previous' });
  }
  return rows;
}

export function complianceDonutSegments(
  checks: { status: string }[] | undefined,
  readinessPercent?: number
): { name: string; value: number; fill: string }[] {
  const list = Array.isArray(checks) ? checks : [];
  const pass = list.filter((c) => c.status === 'pass').length;
  const warning = list.filter((c) => c.status === 'warning').length;
  const gap = list.length - pass - warning;
  if (list.length === 0 && typeof readinessPercent === 'number') {
    const ready = Math.max(0, Math.min(100, readinessPercent));
    return [
      { name: 'Ready', value: ready, fill: '#059669' },
      { name: 'Gap', value: 100 - ready, fill: '#e2e8f0' },
    ];
  }
  if (list.length === 0) {
    return [];
  }
  const segments: { name: string; value: number; fill: string }[] = [];
  if (pass > 0) {
    segments.push({ name: 'On track', value: pass, fill: '#059669' });
  }
  if (warning > 0) {
    segments.push({ name: 'Needs review', value: warning, fill: '#f59e0b' });
  }
  if (gap > 0) {
    segments.push({ name: 'Open gap', value: gap, fill: '#ef4444' });
  }
  return segments;
}
